/**
 * GUIKit Memory Strategy
 * 
 * Hierarchical memory management for GUI data:
 * 1. External RAM (23LC1024 SRAM) - Primary storage
 * 2. SD Card Swap - Secondary storage (for large GUIs)
 * 3. Internal RAM - Fallback storage
 * 
 * Strategy:
 * - If external RAM is available and GUI fits => use external RAM
 * - Else if SD card is available => use SD card swap (streaming/partial loading)
 * - Else => use internal RAM (with memory limit checking)
 * 
 * Generated by Mistral Vibe
 * Date: 2026-08-15
 */

#ifndef GUI_MEMORY_STRATEGY_H
#define GUI_MEMORY_STRATEGY_H

#include <stdint.h>
#include <stdbool.h>
#include "widget_pool.h"

// Forward declarations
class SPISRAM;
class SDCard;
class TFT_ST7789;

// ============================================================================
// Memory Strategy Levels
// ============================================================================

typedef enum {
    MEMORY_STRATEGY_EXTERNAL_RAM = 0,  // Use external SRAM (preferred)
    MEMORY_STRATEGY_SD_SWAP,          // Use SD card as swap/streaming storage
    MEMORY_STRATEGY_INTERNAL_RAM,    // Use internal RAM (fallback)
    MEMORY_STRATEGY_FAILED            // All strategies failed
} MemoryStrategyLevel;

// ============================================================================
// Memory Strategy Configuration
// ============================================================================

// Thresholds for strategy selection
#define MEMORY_STRATEGY_EXTERNAL_RAM_MIN_SIZE 4096    // Min size to use external RAM
#define MEMORY_STRATEGY_SD_SWAP_MIN_SIZE 16384        // Min size to use SD swap
#define MEMORY_STRATEGY_INTERNAL_RAM_MAX_SIZE (8 * 1024)  // Max for internal RAM (8KB)

// External RAM address range for GUI
#define GUI_EXTERNAL_RAM_BASE_ADDR 0x000000
#define GUI_EXTERNAL_RAM_MAX_SIZE (128 * 1024)  // 128KB for 23LC1024

// SD Card swap configuration
#define SD_SWAP_BLOCK_SIZE 512  // SD card sector size
#define SD_SWAP_CACHE_SIZE 2048  // Cache size for streaming

// ============================================================================
// Memory Strategy Result
// ============================================================================

typedef struct {
    MemoryStrategyLevel level;        // Which strategy was used
    bool success;                      // Whether loading succeeded
    uint32_t gui_size;                // Size of GUI JSON in bytes
    uint32_t memory_used;             // Memory used by this strategy
    const char* storage_location;    // Human-readable location
    
    // Strategy-specific data
    union {
        struct {
            uint32_t sram_addr;        // Address in external RAM
            SPISRAM* sram;            // SRAM instance used
        } external_ram;
        
        struct {
            const char* filepath;     // Path on SD card
            uint32_t cache_addr;       // Cache address in internal RAM
            uint32_t cache_size;       // Size of cached data
        } sd_swap;
        
        struct {
            void* gui_ptr;            // Pointer to GUI in internal RAM
        } internal_ram;
    } data;
    
    const char* error_message;        // Error message if failed
} MemoryStrategyResult;

// ============================================================================
// Main Strategy Functions
// ============================================================================

/**
 * Initialize memory strategy system
 * 
 * @param sram Pointer to external SRAM instance (can be NULL)
 * @param sdcard Pointer to SD card instance (can be NULL)
 * @param tft Pointer to TFT for error display (can be NULL)
 */
void gui_memory_strategy_init(SPISRAM* sram, SDCard* sdcard, TFT_ST7789* tft);

/**
 * Load GUI using the best available memory strategy
 * 
 * Strategy order:
 * 1. Try external RAM first (if available and GUI fits)
 * 2. Try SD card swap (if SD card available)
 * 3. Fall back to internal RAM (with memory check)
 * 
 * @param filepath Path to GUI JSON file
 * @return MemoryStrategyResult with loading information
 */
MemoryStrategyResult gui_memory_strategy_load(const char* filepath);

/**
 * Load GUI JSON string using the best available memory strategy
 * 
 * @param json GUI JSON string
 * @return MemoryStrategyResult with loading information
 */
MemoryStrategyResult gui_memory_strategy_load_json(const char* json);

/**
 * Load GUI from WebDAV using the best available memory strategy
 * 
 * @param filename GUI filename on WebDAV
 * @return MemoryStrategyResult with loading information
 */
MemoryStrategyResult gui_memory_strategy_load_webdav(const char* filename);

// ============================================================================
// Strategy Selection Functions
// ============================================================================

/**
 * Determine which memory strategy to use based on GUI size
 * 
 * @param gui_size Size of GUI JSON in bytes
 * @param sram_available true if external RAM is available
 * @param sdcard_available true if SD card is available
 * @return MemoryStrategyLevel to use
 */
MemoryStrategyLevel gui_memory_strategy_select(uint32_t gui_size, 
                                                bool sram_available, 
                                                bool sdcard_available);

/**
 * Check if external RAM can hold the GUI
 * 
 * @param gui_size Size of GUI JSON in bytes
 * @return true if external RAM can hold it
 */
bool gui_memory_strategy_can_use_external_ram(uint32_t gui_size);

/**
 * Check if SD swap can handle the GUI
 * 
 * @param gui_size Size of GUI JSON in bytes
 * @return true if SD swap can handle it
 */
bool gui_memory_strategy_can_use_sd_swap(uint32_t gui_size);

/**
 * Check if internal RAM can hold the GUI
 * 
 * @param gui_size Size of GUI JSON in bytes
 * @return true if internal RAM can hold it
 */
bool gui_memory_strategy_can_use_internal_ram(uint32_t gui_size);

// ============================================================================
// Strategy-Specific Functions
// ============================================================================

// --- External RAM Strategy ---

/**
 * Load GUI into external RAM
 * 
 * @param filepath Path to GUI JSON file
 * @return MemoryStrategyResult
 */
MemoryStrategyResult gui_memory_strategy_external_ram(const char* filepath);

/**
 * Load GUI JSON into external RAM
 * 
 * @param json GUI JSON string
 * @return MemoryStrategyResult
 */
MemoryStrategyResult gui_memory_strategy_external_ram_json(const char* json);

/**
 * Get GUI from external RAM
 * 
 * @param sram SPISRAM instance
 * @param addr Address in external RAM
 * @return Pointer to GUI structure
 */
void* gui_memory_strategy_get_from_external_ram(SPISRAM* sram, uint32_t addr);

// --- SD Card Swap Strategy ---

/**
 * Load GUI using SD card swap
 * GUI JSON stays on SD card, only parsed parts loaded to internal RAM
 * 
 * @param filepath Path to GUI JSON file
 * @return MemoryStrategyResult
 */
MemoryStrategyResult gui_memory_strategy_sd_swap(const char* filepath);

/**
 * Load GUI JSON using SD card swap
 * 
 * @param json GUI JSON string (temporarily stored on SD for swap)
 * @return MemoryStrategyResult
 */
MemoryStrategyResult gui_memory_strategy_sd_swap_json(const char* json);

/**
 * Initialize SD swap cache
 * 
 * @param cache_buffer Buffer for caching (must be SD_SWAP_CACHE_SIZE)
 * @return true on success
 */
bool gui_memory_strategy_sd_swap_init(uint8_t* cache_buffer);

/**
 * Flush SD swap cache
 */
void gui_memory_strategy_sd_swap_flush();

// --- Internal RAM Strategy ---

/**
 * Load GUI into internal RAM
 * Uses memory checker to ensure it fits
 * 
 * @param filepath Path to GUI JSON file
 * @return MemoryStrategyResult
 */
MemoryStrategyResult gui_memory_strategy_internal_ram(const char* filepath);

/**
 * Load GUI JSON into internal RAM
 * 
 * @param json GUI JSON string
 * @return MemoryStrategyResult
 */
MemoryStrategyResult gui_memory_strategy_internal_ram_json(const char* json);

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Get current memory strategy configuration
 * 
 * @return String description of current configuration
 */
const char* gui_memory_strategy_get_config();

/**
 * Get current GUI storage location
 * 
 * @return "External RAM", "SD Card Swap", "Internal RAM", or "None"
 */
const char* gui_memory_strategy_get_location();

/**
 * Check if GUI is currently loaded
 * 
 * @return true if a GUI is loaded
 */
bool gui_memory_strategy_is_gui_loaded();

/**
 * Unload current GUI
 */
void gui_memory_strategy_unload();

/**
 * Get memory usage statistics
 * 
 * @param total_ram Output: Total available RAM
 * @param used_ram Output: Used RAM
 * @param free_ram Output: Free RAM
 * @param strategy Output: Current strategy level
 */
void gui_memory_strategy_get_stats(uint32_t* total_ram, uint32_t* used_ram, 
                                    uint32_t* free_ram, MemoryStrategyLevel* strategy);

// ============================================================================
// Error Handling
// ============================================================================

/**
 * Set error callback for memory strategy failures
 * 
 * @param callback Function to call on error
 */
void gui_memory_strategy_set_error_callback(void (*callback)(const char* message));

/**
 * Display error on TFT
 * 
 * @param tft TFT instance
 * @param result MemoryStrategyResult with error info
 */
void gui_memory_strategy_display_error(TFT_ST7789* tft, const MemoryStrategyResult* result);

#endif // GUI_MEMORY_STRATEGY_H
